begin;
create function pg_temp.check_ok(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception '%',label;end if;end $$;
create function pg_temp.refuse(statement text) returns void language plpgsql as $$begin begin execute statement;exception when insufficient_privilege or raise_exception then return;end;raise exception using errcode='XX000',message='Unexpected permission: '||statement;end $$;
do $$declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();cid uuid;dm uuid;m uuid;n uuid;bid uuid;direct uuid;dm_message uuid;settle uuid;s jsonb;begin
 insert into auth.users(id,email,created_at) select id,id||'@example.invalid',now()-interval '30 days' from unnest(array[a,b,c,outsider]) id;
 insert into public.profiles(id,username,display_name) select id,'qa_'||left(replace(id::text,'-',''),20),'QA member' from unnest(array[a,b,c,outsider]) id;
 -- Privileged fixture setup only; production users awaken through the answer RPC.
 insert into public.battle_identities(user_id,class_id,determination_version) select id,'warrior',1 from public.profiles where username like 'qa_%' and id in(select id from auth.users where email like '%@example.invalid') on conflict do nothing;
 insert into public.friend_requests(requester_id,target_id,status) values(a,b,'accepted'),(a,c,'accepted'),(b,c,'accepted');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 cid:=public.kaidra_create_group('Discussion QA',array[b,c]);dm:=public.get_or_create_conversation(b);
 insert into public.messages(conversation_id,sender_id,content,message_type) values(cid,a,'First statement','discussion') returning id into m;
 insert into public.messages(conversation_id,sender_id,content) values(cid,a,'Normal message') returning id into n;
 perform public.kaidra_message_change(m,'edit','Edited before anyone votes');
 perform pg_temp.refuse(format('select public.kaidra_discussion_position(%L,''agree'')',m));
 update public.messages set content='Bypass' where id=m;perform pg_temp.check_ok((select content='Edited before anyone votes' from public.messages where id=m),'Raw author edit bypassed guard');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 perform pg_temp.refuse(format('select public.kaidra_discussion_position(%L,''agree'')',n));
 s:=public.kaidra_discussion_state(cid,array[m])->0;perform pg_temp.check_ok(s->'agree'='null'::jsonb and s->>'total'='0','Pre-vote split leaked');
 perform public.kaidra_discussion_position(m,'agree');perform public.kaidra_discussion_position(m,'disagree');perform public.kaidra_react(m,'😂');
 s:=public.kaidra_discussion_state(cid,array[m])->0;perform pg_temp.check_ok(s->>'total'='1' and s->>'agree'='0' and s->>'disagree'='1' and s->>'own_position'='disagree','Position switch failed');
 perform pg_temp.refuse(format('insert into public.discussion_positions(discussion_message_id,user_id,conversation_id,position) values(%L,%L,%L,''agree'')',m,a,cid));perform pg_temp.check_ok((select count(*)=1 from public.discussion_positions where discussion_message_id=m),'Position duplicate');perform pg_temp.check_ok((select emoji='😂' from public.message_reactions where message_id=m and user_id=b),'Position erased reaction');
 perform public.kaidra_message_ack(cid,array[m],false);perform pg_temp.check_ok(not exists(select 1 from public.message_reads where message_id=m and user_id=b),'Delivery marked read');
 perform public.kaidra_message_ack(cid,array[m],true);perform pg_temp.check_ok((select count(*)=1 from public.message_reads where message_id=m and user_id=b),'Seen receipt missing');perform pg_temp.check_ok(not exists(select 1 from public.message_reads where message_id=n),'Unseen message consumed');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 s:=public.kaidra_discussion_state(cid,array[m])->0;perform pg_temp.check_ok(s->'agree'='null'::jsonb and s->>'total'='1','Unvoted split leaked');perform pg_temp.check_ok(not exists(select 1 from public.discussion_positions where discussion_message_id=m),'Raw votes leaked');perform public.kaidra_discussion_position(m,'agree');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);perform pg_temp.refuse(format('select public.kaidra_message_change(%L,''edit'',''Opposite'')',m));
 bid:=public.kaidra_battle_create(cid,b,'','',jsonb_build_object('entry_type','discussion','discussion_message_id',m));perform pg_temp.check_ok((select type='discussion' and discussion_message_id=m and status='pending' from public.battles where id=bid),'Discussion reference missing');perform pg_temp.refuse(format('select public.kaidra_battle_action(%L,''accept'')',bid));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);perform pg_temp.refuse(format('select public.kaidra_battle_action(%L,''accept'')',bid));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);perform public.kaidra_battle_action(bid,'accept');perform pg_temp.check_ok((select challenged_position='disagree' and status='active' from public.battles where id=bid),'Acceptance lost context');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);direct:=public.kaidra_battle_create(cid,c,'Flavour text','',jsonb_build_object('entry_type','direct'));perform pg_temp.check_ok((select type='direct' and challenger_position is null and discussion_message_id is null and flavour_text='Flavour text' from public.battles where id=direct),'Direct requires opinion');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);perform public.kaidra_battle_action(direct,'accept');perform pg_temp.check_ok((select status='active' and challenged_position is null from public.battles where id=direct),'Direct acceptance required stance');perform pg_temp.refuse(format('select public.kaidra_battle_action(%L,''post'',''Argument'')',direct));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);dm:=public.get_or_create_conversation(c);insert into public.messages(conversation_id,sender_id,content,message_type) values(dm,b,'DM claim','discussion') returning id into dm_message;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);perform public.kaidra_discussion_position(dm_message,'disagree');s:=public.kaidra_discussion_state(dm,array[dm_message])->0;perform pg_temp.check_ok(s->'dm_response'->>'position'='disagree' and jsonb_array_length(s->'opponents')=1,'DM opposition missing');
 settle:=public.kaidra_battle_create(dm,b,'','',jsonb_build_object('entry_type','discussion','discussion_message_id',dm_message));perform pg_temp.check_ok((select status='pending' and discussion_message_id=dm_message from public.battles where id=settle),'Settle It auto-started or lost reference');perform pg_temp.refuse(format('select public.kaidra_battle_action(%L,''accept'')',settle));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true);perform pg_temp.refuse(format('select public.kaidra_discussion_position(%L,''agree'')',m));perform pg_temp.refuse(format('select public.kaidra_message_ack(%L,array[%L::uuid],true)',cid,m));perform pg_temp.refuse(format('select public.kaidra_discussion_state(%L)',cid));perform pg_temp.check_ok(not public.kaidra_typing_topic('typing:'||cid||':1'),'Outsider joined typing');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);perform pg_temp.check_ok(public.kaidra_typing_topic('typing:'||cid||':'||(select typing_revision from public.conversations where id=cid)),'Member typing denied');perform public.kaidra_discussion_position(m,null);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);perform pg_temp.refuse(format('select public.kaidra_message_change(%L,''edit'',''Still locked'')',m));perform public.kaidra_message_change(m,'delete');perform pg_temp.check_ok((select deleted_at is not null from public.messages where id=m),'Cannot delete voted discussion');execute 'reset role';
end $$;
rollback;
